import { HandlebarsContentEngine, } from '../content/content.engine';
export class ChatHandler {
    message;
    provider;
    contentEngine;
    constructor(message, provider, contentEngine) {
        this.message = message;
        this.provider = provider;
        this.contentEngine = contentEngine ?? new HandlebarsContentEngine();
    }
    async send(data) {
        let content = '';
        if (typeof this.message.template === 'string') {
            content = this.contentEngine.compileTemplate(this.message.template, data);
        }
        else {
            content = await this.message.template(data);
        }
        if (!data.$webhookUrl) {
            throw new Error('webhookUrl is missing in trigger payload. To send an a chat message you must specify a webhookUrl property.');
        }
        return await this.provider.sendMessage({
            webhookUrl: data.$webhookUrl,
            content,
        });
    }
}
